-- Traducciones de mensajes
INSERT INTO public.system_message_translations (message_key, message_key_id, language_code, translated_text, is_active)
SELECT k.message_key, k.id, l.code,
  CASE
    WHEN k.message_key = 'MSG.LOGIN.WELCOME' AND l.code = 'en' THEN 'Welcome'
    WHEN k.message_key = 'MSG.ONBOARDING.START' AND l.code = 'en' THEN 'Initial setup'
    WHEN k.message_key = 'MSG.ONBOARDING.STEP1' AND l.code = 'en' THEN 'Step 1: Create Tenant'
    WHEN k.message_key = 'MSG.ONBOARDING.STEP2' AND l.code = 'en' THEN 'Step 2: Create Administrator'
    WHEN k.message_key = 'MSG.ONBOARDING.COMPLETE' AND l.code = 'en' THEN 'Setup completed'
    ELSE k.default_text
  END AS translated_text,
  true
FROM public.system_message_keys k
CROSS JOIN public.system_languages l
WHERE k.message_key IN ('MSG.LOGIN.WELCOME','MSG.ONBOARDING.START','MSG.ONBOARDING.STEP1','MSG.ONBOARDING.STEP2','MSG.ONBOARDING.COMPLETE')
  AND l.code IN ('es','en')
ON CONFLICT (message_key, language_code) DO UPDATE SET
  message_key_id = EXCLUDED.message_key_id,
  translated_text = EXCLUDED.translated_text,
  is_active = EXCLUDED.is_active;

-- KV store
INSERT INTO public.kv_store_e19f2094 (key, value)
VALUES ('seed.version', jsonb_build_object('script','002_SEED_COMPLETE.sql','version','2026-07-23-FACTORY-V17'))
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;

-- ============================================================================
-- SECCIÓN 1: TENANT ÚNICO + 5 ROLES BASE (PROTOCOLO SELLADO)
-- ============================================================================

-- ✅ Tenant ÚNICO (la empresa que usa el sistema - protocolo SELLADO)
-- Este es el ÚNICO tenant permitido en la instalación On-Premise Enterprise
INSERT INTO public.tenants (tenant_key, tenant_name, is_active)
VALUES ('SYSTEM', 'Titanium-Labs Corp.', true)
ON CONFLICT (tenant_key) DO NOTHING;

-- ✅ 5 Roles Base del Sistema (pertenecen al tenant único SYSTEM)
DO $$
DECLARE v_tenant_id UUID;
BEGIN
  SELECT id INTO v_tenant_id FROM public.tenants WHERE tenant_key = 'SYSTEM';
  IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'ERROR: TENANT SYSTEM no existe'; END IF;

  INSERT INTO public.roles (tenant_id, role_key, role_name, role_scope, is_system_role, is_locked, data_scope, is_tenant_administrator, is_employee_self_service, ui_dashboard_mode, ui_home_route, is_active, created_by) VALUES
  (v_tenant_id, 'SYSTEM_ADMIN', 'System Administrator', 'SYSTEM', true, true, 'ALL', false, false, 'PLATFORM', '/dashboard', true, 'SYSTEM'),
  (v_tenant_id, 'TENANT_ADMIN', 'Administrador del Tenant', 'TENANT', true, true, 'ALL', true, false, 'TENANT', '/dashboard', true, 'SYSTEM'),
  (v_tenant_id, 'RRHH_ADMIN', 'Administrador de RRHH', 'SCOPE', true, true, 'ALL', false, false, 'WORKFORCE', '/dashboard', true, 'SYSTEM'),
  (v_tenant_id, 'SUPERVISOR', 'Supervisor', 'SCOPE', true, true, 'DIRECT_REPORTS', false, false, 'WORKFORCE', '/dashboard', true, 'SYSTEM'),
  (v_tenant_id, 'EMPLOYEE', 'Empleado', 'SCOPE', true, true, 'SELF', false, true, 'SELF', '/kiosk/timeclock', true, 'SYSTEM')
  ON CONFLICT (tenant_id, role_key) DO UPDATE SET
    role_name = EXCLUDED.role_name,
    data_scope = EXCLUDED.data_scope,
    is_tenant_administrator = EXCLUDED.is_tenant_administrator,
    is_employee_self_service = EXCLUDED.is_employee_self_service,
    ui_dashboard_mode = EXCLUDED.ui_dashboard_mode,
    ui_home_route = EXCLUDED.ui_home_route,
    is_locked = true;

  -- Gobierno de usuarios persistente y sin listas de roles en el backend.
  -- SYSTEM_ADMIN administra únicamente usuarios SYSTEM_ADMIN/TENANT_ADMIN.
  UPDATE public.roles target
  SET user_manager_role_id = manager.id,
      is_org_scope_target = false,
      is_employee_access_target = false,
      updated_by = 'SYSTEM',
      updated_at = now()
  FROM public.roles manager
  WHERE manager.tenant_id = target.tenant_id
    AND manager.role_key = 'SYSTEM_ADMIN'
    AND target.tenant_id = v_tenant_id
    AND target.role_key IN ('SYSTEM_ADMIN', 'TENANT_ADMIN');

  -- TENANT_ADMIN administra los usuarios operativos del tenant.
  UPDATE public.roles target
  SET user_manager_role_id = manager.id,
      is_org_scope_target = target.role_key IN ('RRHH_ADMIN', 'SUPERVISOR'),
      is_employee_access_target = target.role_key IN ('RRHH_ADMIN', 'SUPERVISOR'),
      updated_by = 'SYSTEM',
      updated_at = now()
  FROM public.roles manager
  WHERE manager.tenant_id = target.tenant_id
    AND manager.role_key = 'TENANT_ADMIN'
    AND target.tenant_id = v_tenant_id
    AND target.role_key IN ('RRHH_ADMIN', 'SUPERVISOR', 'EMPLOYEE');

  IF EXISTS (
    SELECT 1 FROM public.roles
    WHERE tenant_id = v_tenant_id
      AND role_key IN ('SYSTEM_ADMIN', 'TENANT_ADMIN', 'RRHH_ADMIN', 'SUPERVISOR', 'EMPLOYEE')
      AND user_manager_role_id IS NULL
  ) THEN
    RAISE EXCEPTION 'ERROR: existen roles base sin responsable de administración de usuarios';
  END IF;
    
  RAISE NOTICE '✅ Tenant único creado: SYSTEM';
  RAISE NOTICE '✅ 5 roles base creados bajo tenant SYSTEM';
END $$;

