-- HOLIDAY_TYPE (10 tipos activos con presentacion guiada por metadata)
INSERT INTO public.lookup_values (
  tenant_id, lookup_group_id, lookup_key, lookup_label, lookup_short_label,
  lookup_scope, sort_order, is_active, metadata, created_by
)
SELECT
  NULL, lg.id, vals.key, vals.label, vals.short_label,
  'SYSTEM', vals.sort, true,
  jsonb_build_object(
    'icon_key', vals.icon_key,
    'icon_glyph', vals.icon_glyph,
    'icon_color', vals.icon_color
  ),
  'SYSTEM'
FROM public.lookup_groups lg, LATERAL (VALUES
  ('BIRTHDAY', 'Cumpleaños', 'Cumpleaños', 10, 'Cake', '🎂', '#f59e0b'),
  ('CIVIC', 'Cívico', 'Cívico', 20, 'Flag', '🚩', '#2563eb'),
  ('RELIGIOUS', 'Religioso', 'Religioso', 30, 'Church', '⛪', '#7c3aed'),
  ('NATIONAL', 'Nacional', 'Nacional', 40, 'Landmark', '🏛️', '#1d4ed8'),
  ('MUNICIPAL', 'Municipal', 'Municipal', 50, 'Building2', '🏢', '#0f766e'),
  ('CORPORATE', 'Corporativo', 'Corporativo', 60, 'BriefcaseBusiness', '💼', '#374151'),
  ('COMMEMORATIVE', 'Conmemoración', 'Conmemoración', 70, 'Ribbon', '🎗️', '#db2777'),
  ('CULTURAL', 'Cultural', 'Cultural', 80, 'Theater', '🎭', '#9333ea'),
  ('SPORTS', 'Deportivo', 'Deportivo', 90, 'Trophy', '🏆', '#16a34a'),
  ('OTHER', 'Otro', 'Otro', 100, 'CalendarDays', '📅', '#0ea5e9')
) AS vals(key, label, short_label, sort, icon_key, icon_glyph, icon_color)
WHERE lg.lookup_group_key = 'HOLIDAY_TYPE'
ON CONFLICT ON CONSTRAINT uq_lookup_values DO UPDATE SET
  lookup_label = EXCLUDED.lookup_label,
  lookup_short_label = EXCLUDED.lookup_short_label,
  sort_order = EXCLUDED.sort_order,
  is_active = true,
  metadata = COALESCE(public.lookup_values.metadata, '{}'::jsonb) || EXCLUDED.metadata,
  updated_by = 'SYSTEM',
  updated_at = now();

UPDATE public.lookup_values lv
SET is_active = false,
    updated_by = 'SYSTEM',
    updated_at = now()
FROM public.lookup_groups lg
WHERE lg.lookup_group_key = 'HOLIDAY_TYPE'
  AND lv.lookup_group_id = lg.id
  AND UPPER(lv.lookup_key) NOT IN (
    'BIRTHDAY', 'CIVIC', 'RELIGIOUS', 'NATIONAL', 'MUNICIPAL',
    'CORPORATE', 'COMMEMORATIVE', 'CULTURAL', 'SPORTS', 'OTHER'
  )
  AND lv.is_active = true;

