-- REGLAS PARAMETRIZABLES DE MÉTODOS POR JUSTIFICACIÓN O EVENTO
CREATE TABLE IF NOT EXISTS public.absence_justify_method_rules (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL REFERENCES public.tenants(id),
  justification_type_id uuid NULL REFERENCES public.justification_types(id),
  attendance_event_id uuid NULL REFERENCES public.attendance_events(id),
  justify_method_id uuid NOT NULL REFERENCES public.lookup_values(id),
  sort_order integer NOT NULL DEFAULT 10,
  is_active boolean NOT NULL DEFAULT true,
  created_by character varying NOT NULL,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_by character varying NULL,
  updated_at timestamp with time zone NULL,
  CONSTRAINT absence_justify_method_rules_scope_chk CHECK (
    (justification_type_id IS NOT NULL AND attendance_event_id IS NULL)
    OR (justification_type_id IS NULL AND attendance_event_id IS NOT NULL)
  )
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_absence_justify_method_rules_justification
  ON public.absence_justify_method_rules (
    tenant_id,
    justification_type_id,
    justify_method_id
  )
  WHERE justification_type_id IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS uq_absence_justify_method_rules_event
  ON public.absence_justify_method_rules (
    tenant_id,
    attendance_event_id,
    justify_method_id
  )
  WHERE attendance_event_id IS NOT NULL;

WITH tenant AS (
  SELECT id
  FROM public.tenants
  WHERE tenant_key = 'SYSTEM'
  LIMIT 1
), methods AS (
  SELECT lv.id, lv.lookup_key
  FROM public.lookup_values lv
  JOIN public.lookup_groups lg
    ON lg.id = lv.lookup_group_id
  WHERE lg.lookup_group_key = 'JUSTIFY_METHOD'
    AND lv.is_active = true
), rules(scope_type, scope_key, method_key, sort_order) AS (
  VALUES
    ('EVENT', 'FAL', 'VACACIONES', 10),
    ('EVENT', 'FAL', 'SIN_SUELDO', 20),
    ('JUSTIFICATION', 'Permiso', 'VACACIONES', 10),
    ('JUSTIFICATION', 'Permiso', 'CON_SUELDO', 20),
    ('JUSTIFICATION', 'Permiso', 'SIN_SUELDO', 30)
), resolved AS (
  SELECT
    tenant.id AS tenant_id,
    CASE WHEN rules.scope_type = 'JUSTIFICATION' THEN jt.id END AS justification_type_id,
    CASE WHEN rules.scope_type = 'EVENT' THEN ae.id END AS attendance_event_id,
    methods.id AS justify_method_id,
    rules.sort_order
  FROM tenant
  CROSS JOIN rules
  JOIN methods
    ON methods.lookup_key = rules.method_key
  LEFT JOIN public.justification_types jt
    ON rules.scope_type = 'JUSTIFICATION'
   AND jt.tenant_id = tenant.id
   AND jt.justification_short_name = rules.scope_key
  LEFT JOIN public.attendance_events ae
    ON rules.scope_type = 'EVENT'
   AND ae.tenant_id = tenant.id
   AND ae.event_short_name = rules.scope_key
)
INSERT INTO public.absence_justify_method_rules (
  tenant_id,
  justification_type_id,
  attendance_event_id,
  justify_method_id,
  sort_order,
  is_active,
  created_by
)
SELECT
  tenant_id,
  justification_type_id,
  attendance_event_id,
  justify_method_id,
  sort_order,
  true,
  'SYSTEM'
FROM resolved rule
WHERE (rule.justification_type_id IS NOT NULL OR rule.attendance_event_id IS NOT NULL)
  AND NOT EXISTS (
    SELECT 1
    FROM public.absence_justify_method_rules current
    WHERE current.tenant_id = rule.tenant_id
      AND current.justification_type_id IS NOT DISTINCT FROM rule.justification_type_id
      AND current.attendance_event_id IS NOT DISTINCT FROM rule.attendance_event_id
      AND current.justify_method_id = rule.justify_method_id
  );

-- SYSTEM REPORTS REQUIRED BY REPORT PARAMETERS
