  VALUES
    ('RPT_ANOMALIAS_ASISTENCIA', 'Anomalias de asistencia', 'Reporte independiente de anomalias que afectan la calidad del calculo de asistencia.', 'REPORT_HANDLER', 'DEFAULT', 'attendance.anomalies', 'APPLICATION_MODULE', 'REPORTS', true),
    ('RPT_HORA_EXTRA_DETA', 'Horas y sobretiempos detallado', 'Reporte detallado por empleado y fecha con turno, marcaciones, horas trabajadas, ausentismos y descuentos.', 'REPORT_HANDLER', 'DEFAULT', 'overtime.detail', 'APPLICATION_MODULE', 'REPORTS', true),
    ('RPT_HORA_EXTRA_RESU', 'Horas y sobretiempos resumido', 'Reporte consolidado de horas y sobretiempos por empleado para el periodo.', 'REPORT_HANDLER', 'DEFAULT', 'overtime.summary', 'APPLICATION_MODULE', 'REPORTS', true),
    ('RPT_MARCACIONES_REALIZADAS', 'Marcaciones realizadas', 'Detalle jerarquizado de marcaciones por empleado y estructura organizacional, con dispositivo, coordenadas GPS y turno asignado.', 'REPORT_HANDLER', 'DEFAULT', 'attendance.punches', 'APPLICATION_MODULE', 'REPORTS', true),
    ('RPT_RUTA_RECORRIDA', 'Ruta recorrida', 'Reporte de recorrido de empleados segun marcaciones y ubicaciones disponibles.', 'REPORT_HANDLER', 'DEFAULT', 'route.tracking', 'APPLICATION_MODULE', 'REPORTS', true)
), resolved AS (
  SELECT data.*, handler.id AS handler_type_id, app.id AS application_module_id FROM data JOIN public.lookup_groups hg ON hg.lookup_group_key = data.handler_group JOIN public.lookup_values handler ON handler.lookup_group_id = hg.id AND handler.lookup_key = data.handler_key AND handler.tenant_id IS NULL LEFT JOIN public.lookup_groups ag ON ag.lookup_group_key = data.application_group LEFT JOIN public.lookup_values app ON app.lookup_group_id = ag.id AND app.lookup_key = data.application_key AND app.tenant_id IS NULL
) INSERT INTO public.system_reports (report_code, report_name, report_description, handler_type_id, report_handler, application_module_id, is_active, created_by)
SELECT report_code, report_name, report_description, handler_type_id, report_handler, application_module_id, is_active, 'SYSTEM' FROM resolved
ON CONFLICT (report_code) DO UPDATE SET report_name = EXCLUDED.report_name, report_description = EXCLUDED.report_description, handler_type_id = EXCLUDED.handler_type_id, report_handler = EXCLUDED.report_handler, application_module_id = EXCLUDED.application_module_id, is_active = EXCLUDED.is_active, updated_by = 'SYSTEM', updated_at = now();

