    ('RPT_MARCACIONES_REALIZADAS', 'WORK_GROUP_ID', 'Grupo de Trabajo', 'Grupo de trabajo. Valor ALL para todos.', 'DATA_TYPE', 'STRING', 'UI_CONTROL', 'SELECT', false, 'ALL', NULL, false, 90, true),
