    ('RPT_RUTA_RECORRIDA', 'EMPLOYEE_SEARCH', 'Buscar', 'Texto libre para filtrar por nombre, identificacion o codigo del empleado.', 'DATA_TYPE', 'STRING', 'UI_CONTROL', 'TEXT', false, NULL, NULL, false, 20, true),
    ('RPT_RUTA_RECORRIDA', 'DATE_FROM', 'Desde', 'Fecha inicial del periodo del reporte.', 'DATA_TYPE', 'DATE', 'UI_CONTROL', 'DATE', true, NULL, NULL, false, 30, true),
    ('RPT_RUTA_RECORRIDA', 'DATE_TO', 'Hasta', 'Fecha final del periodo del reporte.', 'DATA_TYPE', 'DATE', 'UI_CONTROL', 'DATE', true, NULL, NULL, false, 40, true),
    ('RPT_RUTA_RECORRIDA', 'DEPARTMENT_ID', 'Departamento', 'Departamento organizacional. Valor ALL para todos.', 'DATA_TYPE', 'STRING', 'UI_CONTROL', 'SELECT', false, 'ALL', NULL, false, 50, true),
    ('RPT_RUTA_RECORRIDA', 'AREA_ID', 'Area', 'Area organizacional. Valor ALL para todas.', 'DATA_TYPE', 'STRING', 'UI_CONTROL', 'SELECT', false, 'ALL', NULL, false, 60, true),
    ('RPT_RUTA_RECORRIDA', 'PAYROLL_GROUP_ID', 'Rol de Pago', 'Rol de pago. Valor ALL para todos.', 'DATA_TYPE', 'STRING', 'UI_CONTROL', 'SELECT', false, 'ALL', NULL, false, 70, true),
    ('RPT_RUTA_RECORRIDA', 'COST_CENTER_ID', 'Centro de Costo', 'Centro de costo. Valor ALL para todos.', 'DATA_TYPE', 'STRING', 'UI_CONTROL', 'SELECT', false, 'ALL', NULL, false, 80, true),
