    ('COMPANY_ASSETS_PATH', 'Carpeta de imágenes de empresas para reportes', 'COMP_ASSETS', 'DATA_TYPE', 'STRING', 'storage/company-assets', 'Ruta base donde se almacenan logos y banners de empresas para reportes.', NULL, true),
    ('EMPLOYEE_PHOTO_PATH', 'Carpeta de fotos de empleados', 'PHOTO_PATH', 'DATA_TYPE', 'STRING', 'storage/employee-photos', 'Localización de las fotos de los empleados.', NULL, true),
    ('GENERAL_DEFAULT_LANGUAGE', 'Idioma por Defecto del Sistema', 'DEF_LANG', 'DATA_TYPE', 'STRING', 'es', 'Idioma por defecto del sistema.', NULL, true),
    ('GENERAL_FISCAL_YEAR_START', 'Inicio del Año Fiscal (MM-DD)', 'FISCAL_START', 'DATA_TYPE', 'STRING', '01-01', 'Fecha de inicio del año fiscal.', NULL, true),
    ('GENERAL_WORKING_WEEK_DAYS', 'Días Laborales de la Semana', 'WORK_DAYS', 'DATA_TYPE', 'STRING', '1,2,3,4,5', 'Días laborales de la semana.', NULL, true),
    ('MIN_MINUTES_BETWEEN_VALID_PUNCHES', 'Minutos mínimos entre marcaciones válidas', 'MIN_PUNCH_MIN', 'DATA_TYPE', 'NUMBER', '5', 'Cantidad mínima de minutos que deben pasar para aceptar una nueva marcación válida del mismo empleado.', NULL, true),
    ('NOTIFICATION_ABSENCE_ENABLED', 'Notificaciones de Ausencia Activas', 'NOTIF_ABS', 'DATA_TYPE', 'LOOKUP', 'TRUE', 'Habilita las notificaciones de ausencia.', 'BOOLEAN_OPTION', true),
    ('NOTIFICATION_OVERTIME_ENABLED', 'Notificaciones de Horas Extra', 'NOTIF_OT', 'DATA_TYPE', 'LOOKUP', 'TRUE', 'Habilita las notificaciones de horas extra.', 'BOOLEAN_OPTION', true),
    ('PAYROLL_CURRENCY_CODE', 'Moneda de Nómina', 'CURRENCY', 'DATA_TYPE', 'LOOKUP', 'USD', 'Moneda utilizada para la nómina.', 'CURRENCY', true),
    ('PAYROLL_EXPORT_FORMAT', 'Formato de Exportación a Nómina', 'PAY_FORMAT', 'DATA_TYPE', 'LOOKUP', 'CSV', 'Formato de archivo para exportar la nómina.', 'OUTPUT_FORMAT', true),
    ('PAYROLL_PERIOD_TYPE', 'Tipo de Período de Nómina', 'PAY_PERIOD', 'DATA_TYPE', 'LOOKUP', 'BIWEEKLY', 'Tipo de período para la nómina (semanal, quincenal, mensual).', 'PAYROLL_PERIOD_TYPE', true),
    ('REQUEST_SUPPORT_DOCS_MAX_SIZE_BYTES', 'Tamaño máximo en bytes para PDF de respaldo', 'REQ_DOC_MAX', 'UI_CONTROL', 'TEXT', '5242880', NULL, NULL, true),
    ('REQUEST_SUPPORT_DOCS_PATH', 'Carpeta de respaldo PDF para solicitudes', 'REQ_DOC_PATH', 'UI_CONTROL', 'TEXT', 'storage/request-support-docs', NULL, NULL, true),
    ('SECURITY_LOGIN_LOCKOUT_MINUTES', 'Duracion del bloqueo de acceso (minutos)', 'LOGIN_LOCK', 'DATA_TYPE', 'NUMBER', '15', 'Tiempo de bloqueo temporal luego de superar los intentos fallidos permitidos.', NULL, true),
    ('SECURITY_MAX_LOGIN_ATTEMPTS', 'Intentos Máximos de Login', 'MAX_LOGIN', 'DATA_TYPE', 'NUMBER', '5', 'Número máximo de intentos de login permitidos.', NULL, true),
    ('SECURITY_PASSWORD_MIN_LENGTH', 'Longitud minima de contrasena', 'PWD_MIN_LEN', 'DATA_TYPE', 'NUMBER', '12', 'Cantidad minima de caracteres exigida para contrasenas nuevas.', NULL, true),
    ('SECURITY_SESSION_TIMEOUT_MIN', 'Timeout de Sesión (minutos)', 'SESSION_TO', 'DATA_TYPE', 'NUMBER', '480', 'Tiempo de inactividad antes de cerrar la sesión.', NULL, true),
    ('SHIFT_ALLOW_OVERLAP', 'Permitir Solapamiento de Turnos', 'ALLOW_OVERLAP', 'DATA_TYPE', 'LOOKUP', 'FALSE', 'Permite que los turnos se solapen.', 'BOOLEAN_OPTION', true),
    ('SHIFT_CHANGE_ADVANCE_DAYS', 'Días de Anticipación Cambio Turno', 'CHG_ADV_DAYS', 'DATA_TYPE', 'NUMBER', '2', 'Días de anticipación para cambiar de turno.', NULL, true),
    ('SHIFT_MAX_CONSECUTIVE_DAYS', 'Días Consecutivos Máximos', 'MAX_CONSEC', 'DATA_TYPE', 'NUMBER', '6', 'Número máximo de días consecutivos que un empleado puede trabajar.', NULL, true)
), resolved AS (
  SELECT
    data.*,
    value_type.id AS value_type_id,
    allowed_group.id AS allowed_lookup_group_id
  FROM data
  JOIN public.lookup_groups value_type_group
    ON value_type_group.lookup_group_key = data.value_type_group_key
  JOIN public.lookup_values value_type
    ON value_type.lookup_group_id = value_type_group.id
   AND value_type.lookup_key = data.value_type_key
   AND value_type.is_active = true
  LEFT JOIN public.lookup_groups allowed_group
    ON allowed_group.lookup_group_key = data.allowed_lookup_group_key
)
