-- Si 002 se reejecuta en una instalacion que ya creo empresas, completa
-- solamente los turnos base que falten y conserva cualquier personalizacion.
SELECT public.apply_system_shift_templates_to_company(company.id)
FROM public.companies AS company
ORDER BY company.created_at, company.id;

-- PATRONES BASE PARA TENANT_ADMIN
-- Los patrones pertenecen al tenant, pero su secuencia referencia los turnos
-- de una empresa. Se crean sus cabeceras desde fabrica y la primera empresa
-- disponible aporta los turnos para completar cada secuencia.
WITH system_tenant AS (
  SELECT tenant.id AS tenant_id
  FROM public.tenants AS tenant
  WHERE tenant.tenant_key = 'SYSTEM'
), pattern_data(
  pattern_name, pattern_short_name, cycle_length_days,
  work_days_per_cycle, rest_days_per_cycle,
  daily_work_minutes, weekly_work_minutes_target, is_flexible
) AS (
  VALUES
    ('Oficina 5x2', 'OFFICE_5X2', 7, 5, 2, 480, 2400, false),
    ('Rotativo 8x2', 'ROTATING_8X2', 8, 6, 2, 480, 2880, false)
)
INSERT INTO public.work_patterns (
  tenant_id, pattern_name, pattern_short_name, cycle_length_days,
  work_days_per_cycle, rest_days_per_cycle,
  daily_work_minutes, weekly_work_minutes_target,
  is_flexible, is_active, created_by
)
SELECT
  system_tenant.tenant_id,
  pattern_data.pattern_name,
  pattern_data.pattern_short_name,
  pattern_data.cycle_length_days,
  pattern_data.work_days_per_cycle,
  pattern_data.rest_days_per_cycle,
  pattern_data.daily_work_minutes,
  pattern_data.weekly_work_minutes_target,
  pattern_data.is_flexible,
  true,
  'SYSTEM_WORK_PATTERN_TEMPLATE'
FROM system_tenant
CROSS JOIN pattern_data
WHERE NOT EXISTS (
  SELECT 1
  FROM public.work_patterns AS existing_pattern
  WHERE existing_pattern.tenant_id = system_tenant.tenant_id
    AND upper(existing_pattern.pattern_short_name) = pattern_data.pattern_short_name
);

CREATE OR REPLACE FUNCTION public.apply_system_work_patterns_to_company(p_company_id uuid)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
  company_tenant_id uuid;
  office_pattern_id uuid;
  rotating_pattern_id uuid;
  office_shift_id uuid;
  morning_shift_id uuid;
  afternoon_shift_id uuid;
  overnight_shift_id uuid;
  free_day_shift_id uuid;
BEGIN
  SELECT company.tenant_id
    INTO company_tenant_id
  FROM public.companies AS company
  WHERE company.id = p_company_id;

  IF company_tenant_id IS NULL THEN
    RAISE EXCEPTION 'No existe la empresa % para instanciar patrones base', p_company_id;
  END IF;

  -- Garantiza que los turnos requeridos existan aunque cambie el orden de los
  -- triggers AFTER INSERT de companies.
  PERFORM public.apply_system_shift_templates_to_company(p_company_id);

  SELECT pattern.id
    INTO office_pattern_id
  FROM public.work_patterns AS pattern
  WHERE pattern.tenant_id = company_tenant_id
    AND upper(pattern.pattern_short_name) = 'OFFICE_5X2'
  ORDER BY pattern.created_at, pattern.id
  LIMIT 1;

  SELECT pattern.id
    INTO rotating_pattern_id
  FROM public.work_patterns AS pattern
  WHERE pattern.tenant_id = company_tenant_id
    AND upper(pattern.pattern_short_name) = 'ROTATING_8X2'
  ORDER BY pattern.created_at, pattern.id
  LIMIT 1;

  SELECT shift.id INTO office_shift_id
  FROM public.shifts AS shift
  WHERE shift.tenant_id = company_tenant_id
    AND shift.company_id = p_company_id
    AND shift.shift_short_name = 'OFI'
  ORDER BY shift.created_at, shift.id
  LIMIT 1;

  SELECT shift.id INTO morning_shift_id
  FROM public.shifts AS shift
  WHERE shift.tenant_id = company_tenant_id
    AND shift.company_id = p_company_id
    AND shift.shift_short_name = 'MAT'
  ORDER BY shift.created_at, shift.id
  LIMIT 1;

  SELECT shift.id INTO afternoon_shift_id
  FROM public.shifts AS shift
  WHERE shift.tenant_id = company_tenant_id
    AND shift.company_id = p_company_id
    AND shift.shift_short_name = 'VES'
  ORDER BY shift.created_at, shift.id
  LIMIT 1;

  SELECT shift.id INTO overnight_shift_id
  FROM public.shifts AS shift
  WHERE shift.tenant_id = company_tenant_id
    AND shift.company_id = p_company_id
    AND shift.shift_short_name = 'AMA'
  ORDER BY shift.created_at, shift.id
  LIMIT 1;

  SELECT shift.id INTO free_day_shift_id
  FROM public.shifts AS shift
  WHERE shift.tenant_id = company_tenant_id
    AND shift.company_id = p_company_id
    AND shift.shift_short_name = 'LIB'
  ORDER BY shift.created_at, shift.id
  LIMIT 1;

  IF office_pattern_id IS NULL OR rotating_pattern_id IS NULL THEN
    RAISE EXCEPTION 'No existen los patrones base OFFICE_5X2 y ROTATING_8X2 para el tenant %', company_tenant_id;
  END IF;

  IF office_shift_id IS NULL OR morning_shift_id IS NULL
     OR afternoon_shift_id IS NULL OR overnight_shift_id IS NULL
     OR free_day_shift_id IS NULL THEN
    RAISE EXCEPTION 'No existen todos los turnos base para completar los patrones del tenant %', company_tenant_id;
  END IF;

  -- Conserva cualquier secuencia ya creada o personalizada para el tenant.
  IF NOT EXISTS (
    SELECT 1
    FROM public.work_pattern_shifts AS pattern_shift
    WHERE pattern_shift.work_pattern_id = office_pattern_id
  ) THEN
    INSERT INTO public.work_pattern_shifts (
      tenant_id, work_pattern_id, shift_id,
      sequence_number, cycle_day_number,
      is_active, created_by
    )
    SELECT
      company_tenant_id,
      office_pattern_id,
      sequence.shift_id,
      sequence.sequence_number,
      sequence.sequence_number,
      true,
      'SYSTEM_WORK_PATTERN_TEMPLATE'
    FROM (VALUES
      (1, office_shift_id),
      (2, office_shift_id),
      (3, office_shift_id),
      (4, office_shift_id),
      (5, office_shift_id),
      (6, free_day_shift_id),
      (7, free_day_shift_id)
    ) AS sequence(sequence_number, shift_id)
    ORDER BY sequence.sequence_number;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.work_pattern_shifts AS pattern_shift
    WHERE pattern_shift.work_pattern_id = rotating_pattern_id
  ) THEN
    INSERT INTO public.work_pattern_shifts (
      tenant_id, work_pattern_id, shift_id,
      sequence_number, cycle_day_number,
      is_active, created_by
    )
    SELECT
      company_tenant_id,
      rotating_pattern_id,
      sequence.shift_id,
      sequence.sequence_number,
      sequence.sequence_number,
      true,
      'SYSTEM_WORK_PATTERN_TEMPLATE'
    FROM (VALUES
      (1, morning_shift_id),
      (2, morning_shift_id),
      (3, afternoon_shift_id),
      (4, afternoon_shift_id),
      (5, overnight_shift_id),
      (6, overnight_shift_id),
      (7, free_day_shift_id),
      (8, free_day_shift_id)
    ) AS sequence(sequence_number, shift_id)
    ORDER BY sequence.sequence_number;
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION public.instantiate_system_work_patterns_on_company()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  PERFORM public.apply_system_work_patterns_to_company(NEW.id);
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_companies_seed_system_work_patterns ON public.companies;
CREATE TRIGGER trg_companies_seed_system_work_patterns
AFTER INSERT ON public.companies
FOR EACH ROW
EXECUTE FUNCTION public.instantiate_system_work_patterns_on_company();

-- Si 002 se reejecuta en una instalacion que ya creo empresas, la primera
-- empresa completa las secuencias; las siguientes conservan esa definicion.
SELECT public.apply_system_work_patterns_to_company(company.id)
FROM public.companies AS company
ORDER BY company.created_at, company.id;

