-- ============================================================================
-- ORDEN INICIAL DEL MENU SEGURIDAD PARA SYSTEM ADMIN
-- Catalogos independientes primero; luego pantallas que dependen de ellos.
-- El orden puede modificarse posteriormente desde Gestion de Menus.
-- ============================================================================

-- Roles es un catalogo independiente y pertenece a Mantenimiento.
UPDATE public.screens AS screen
SET menu_group_id = menu_group.id,
    sort_order = 10,
    updated_by = 'SYSTEM',
    updated_at = now()
FROM public.system_menu_groups AS menu_group
WHERE screen.screen_key = 'ROLE_MANAGEMENT'
  AND menu_group.menu_group_key = 'MAINT';

-- Desactiva el duplicado historico solo si nunca tuvo acciones vinculadas.
UPDATE public.screens AS legacy_screen
SET is_active = false,
    updated_by = 'SYSTEM',
    updated_at = now()
WHERE legacy_screen.screen_key = 'ROLES_MANAGEMENT'
  AND NOT EXISTS (
    SELECT 1
    FROM public.screen_actions AS screen_action
    WHERE screen_action.screen_id = legacy_screen.id
  );

WITH dependency_order(screen_key, sort_order) AS (
  VALUES
    ('LANGUAGE_MANAGEMENT', 10),
    ('ACTION_MANAGEMENT', 20),
    ('SEC_ACTIONS', 20),
    ('SCOPE_TYPE_MANAGEMENT', 30),
    ('SUBSCRIPTION_PLAN_MANAGEMENT', 40),
    ('MESSAGE_KEY_MANAGEMENT', 50),
    ('MENU_GROUP_MANAGEMENT', 60),
    ('SEC_MENU_GROUPS', 60),
    ('SCREEN_MANAGEMENT', 70),
    ('SEC_SCREENS', 70),
    ('SEC_SCREEN_ACTIONS', 80),
    ('TRANSLATION_MANAGEMENT', 90),
    ('SYSTEM_REPORT_MANAGEMENT', 100),
    ('TENANT_MANAGEMENT', 110),
    ('CNX_PAYROLL', 120),
    ('USER_MANAGEMENT', 140),
    ('SEC_USER_ROLES', 150),
    ('SEC_ROLE_PERMS', 160),
    ('SEC_ROLE_SCREEN_ACTIONS', 160),
    ('SEC_COPY_PERMS', 170),
    ('SEC_USER_ROLE_SCOPES', 180),
    ('SEC_USER_EMPLOYEE_ACCESS', 190),
    ('SEC_LOGIN_SESSIONS', 200),
    ('SEC_AUDIT', 210)
)
UPDATE public.screens AS screen
SET sort_order = dependency_order.sort_order,
    updated_by = 'SYSTEM',
    updated_at = now()
FROM dependency_order
JOIN public.system_menu_groups AS menu_group
  ON menu_group.menu_group_key = 'SECURITY'
WHERE screen.screen_key = dependency_order.screen_key
  AND screen.menu_group_id = menu_group.id;

-- ============================================================================
-- SECCIÓN 8: RELACIONES PANTALLA-ACCIÓN (screen_actions)
-- ============================================================================

DO $$
DECLARE v_scr UUID; v_act UUID;
BEGIN
  -- USER_MANAGEMENT
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'USER_MANAGEMENT' AND a.action_key IN ('VIEW', 'CREATE', 'EDIT', 'DELETE', 'RESET_PASSWORD')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- ROLE_MANAGEMENT
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'ROLE_MANAGEMENT' AND a.action_key IN ('VIEW', 'CREATE', 'EDIT', 'DELETE', 'CONFIGURE_PERMISSIONS')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- CATALOG_MANAGEMENT
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'CATALOG_MANAGEMENT' AND a.action_key IN ('VIEW', 'CREATE', 'EDIT', 'DELETE')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- SYSTEM_SETTINGS_MANAGEMENT: catálogo maestro para SYSTEM_ADMIN y overrides en grilla para niveles inferiores.
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'SYSTEM_SETTINGS_MANAGEMENT' AND a.action_key IN ('VIEW', 'CREATE', 'EDIT', 'ASSIGN')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- TENANT_SETTINGS
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'TENANT_SETTINGS' AND a.action_key IN ('VIEW', 'EDIT')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- SCHEDULE_MANAGEMENT
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'SCHEDULE_MANAGEMENT' AND a.action_key IN ('VIEW', 'CREATE', 'EDIT', 'DELETE', 'CLONE')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- CALENDAR_MANAGEMENT
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'CALENDAR_MANAGEMENT' AND a.action_key IN ('VIEW', 'CREATE', 'EDIT', 'DELETE')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- DEVICE_MANAGEMENT
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'DEVICE_MANAGEMENT' AND a.action_key IN ('VIEW', 'CREATE', 'EDIT', 'DELETE', 'SYNC', 'TEST')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- PAYROLL_INTEGRATION
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'PAYROLL_INTEGRATION' AND a.action_key IN ('VIEW', 'EDIT', 'TEST', 'SYNC')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- ORG_STRUCTURE
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'ORG_STRUCTURE' AND a.action_key IN ('VIEW', 'CREATE', 'EDIT', 'DELETE')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- EMPLOYEE_MANAGEMENT
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'EMPLOYEE_MANAGEMENT' AND a.action_key IN ('VIEW', 'CREATE', 'EDIT', 'DELETE', 'IMPORT', 'EXPORT')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- REQUESTS_MANAGEMENT
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'REQUESTS_MANAGEMENT' AND a.action_key IN ('VIEW', 'CREATE', 'EDIT', 'DELETE', 'APPROVE', 'REJECT', 'COMMENT')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- TIMECLOCK_MANAGEMENT
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'TIMECLOCK_MANAGEMENT' AND a.action_key IN ('VIEW', 'CREATE', 'EDIT', 'DELETE', 'IMPORT', 'EXPORT')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- EMPLOYEE_SHIFT_PLANNING (pantalla canónica de planificación de turnos)
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'EMPLOYEE_SHIFT_PLANNING' AND a.action_key IN ('VIEW', 'CREATE', 'EDIT', 'DELETE', 'ASSIGN', 'REASSIGN', 'SWAP')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- ATTENDANCE_CALCULATION
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'ATTENDANCE_CALCULATION' AND a.action_key IN ('VIEW', 'EXECUTE', 'RECALCULATE')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- PERIOD_CLOSE
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'PERIOD_CLOSE' AND a.action_key IN ('VIEW', 'CLOSE', 'REOPEN')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- PAYROLL_EXPORT
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'PAYROLL_EXPORT' AND a.action_key IN ('VIEW', 'GENERATE', 'EXPORT', 'DOWNLOAD')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- ANOMALY_MANAGEMENT
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'ANOMALY_MANAGEMENT' AND a.action_key IN ('VIEW', 'RESOLVE', 'COMMENT', 'ASSIGN')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- ATTENDANCE_REPORTS
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'ATTENDANCE_REPORTS' AND a.action_key IN ('VIEW', 'GENERATE', 'EXPORT', 'DOWNLOAD')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- KIOSK_TIMECLOCK
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'KIOSK_TIMECLOCK' AND a.action_key IN ('VIEW', 'PUNCH')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- MY_REQUESTS
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'MY_REQUESTS' AND a.action_key IN ('VIEW', 'CREATE', 'CANCEL')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- MY_ATTENDANCE
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'MY_ATTENDANCE' AND a.action_key IN ('VIEW')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- MY_SCHEDULE
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a WHERE s.screen_key = 'MY_SCHEDULE' AND a.action_key IN ('VIEW')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;

  -- Pantallas SYSTEM (pendientes): VIEW, CREATE, EDIT, DELETE
  FOR v_scr, v_act IN SELECT s.id, a.id FROM screens s, actions a 
  WHERE s.screen_key IN ('TENANT_MANAGEMENT','MENU_GROUP_MANAGEMENT','SCREEN_MANAGEMENT','ACTION_MANAGEMENT','SCOPE_TYPE_MANAGEMENT','LANGUAGE_MANAGEMENT','MESSAGE_KEY_MANAGEMENT','TRANSLATION_MANAGEMENT','SYSTEM_REPORT_MANAGEMENT','SUBSCRIPTION_PLAN_MANAGEMENT') 
  AND a.action_key IN ('VIEW', 'CREATE', 'EDIT', 'DELETE')
  LOOP INSERT INTO screen_actions (screen_id, action_id, is_active, created_by) VALUES (v_scr, v_act, true, 'SYSTEM') ON CONFLICT DO NOTHING; END LOOP;
END $$;

-- ============================================================================
-- SECCIÓN 9: PERMISOS DE MENÚ (role_screen_actions)
-- ============================================================================

DO $$
DECLARE
  v_tenant_system_id UUID;
  v_role_system_admin UUID; v_role_tenant_admin UUID; v_role_rrhh_admin UUID;
  v_role_supervisor UUID; v_role_employee UUID;
BEGIN
  SELECT id INTO v_tenant_system_id FROM public.tenants WHERE tenant_key = 'SYSTEM';
  SELECT id INTO v_role_system_admin FROM public.roles WHERE role_key = 'SYSTEM_ADMIN' AND tenant_id = v_tenant_system_id;
  SELECT id INTO v_role_tenant_admin FROM public.roles WHERE role_key = 'TENANT_ADMIN' AND tenant_id = v_tenant_system_id;
  SELECT id INTO v_role_rrhh_admin FROM public.roles WHERE role_key = 'RRHH_ADMIN' AND tenant_id = v_tenant_system_id;
  SELECT id INTO v_role_supervisor FROM public.roles WHERE role_key = 'SUPERVISOR' AND tenant_id = v_tenant_system_id;
  SELECT id INTO v_role_employee FROM public.roles WHERE role_key = 'EMPLOYEE' AND tenant_id = v_tenant_system_id;

  -- SYSTEM_ADMIN: SECURITY + MAINT + todas las pantallas de Organización.
  INSERT INTO public.role_screen_actions (tenant_id, role_id, screen_action_id, is_allowed, created_by)
  SELECT v_tenant_system_id, v_role_system_admin, sa.id, true, 'SYSTEM'
  FROM public.screen_actions sa
  JOIN public.screens s ON sa.screen_id = s.id
  JOIN public.system_menu_groups smg ON s.menu_group_id = smg.id
  WHERE (
      smg.menu_group_key IN ('SECURITY', 'MAINT')
      OR (
        smg.menu_group_key = 'ORG'
        AND smg.is_active = true
        AND s.is_active = true
        AND sa.is_active = true
      )
    )
    AND s.screen_key NOT IN ('SEC_USER_ROLE_SCOPES', 'SEC_USER_EMPLOYEE_ACCESS')
  ON CONFLICT (tenant_id, role_id, screen_action_id) DO UPDATE SET is_allowed = true;

  -- TENANT_ADMIN: MAINT, CONFIG, ORG
  INSERT INTO public.role_screen_actions (tenant_id, role_id, screen_action_id, is_allowed, created_by)
  SELECT v_tenant_system_id, v_role_tenant_admin, sa.id, true, 'SYSTEM'
  FROM public.screen_actions sa
  JOIN public.screens s ON sa.screen_id = s.id
  JOIN public.system_menu_groups smg ON s.menu_group_id = smg.id
  WHERE smg.menu_group_key IN ('MAINT', 'CONFIG', 'ORG')
    AND s.screen_key <> 'SYSTEM_SETTINGS_MANAGEMENT'
  ON CONFLICT (tenant_id, role_id, screen_action_id) DO UPDATE SET is_allowed = true;

  -- TENANT_ADMIN: consulta el catálogo heredado y edita únicamente setting_value
  -- en tenant_settings, company_settings, employee_profile_settings y employee_settings.
  INSERT INTO public.role_screen_actions (tenant_id, role_id, screen_action_id, is_allowed, created_by)
  SELECT v_tenant_system_id, v_role_tenant_admin, sa.id, true, 'SYSTEM'
  FROM public.screen_actions sa
  JOIN public.screens s ON sa.screen_id = s.id
  JOIN public.actions a ON a.id = sa.action_id
  WHERE s.screen_key = 'SYSTEM_SETTINGS_MANAGEMENT'
    AND a.action_key IN ('VIEW', 'EDIT', 'ASSIGN')
    AND sa.is_active = true
  ON CONFLICT (tenant_id, role_id, screen_action_id) DO UPDATE SET
    is_allowed = true,
    is_active = true,
    updated_by = 'SYSTEM',
    updated_at = now();

  -- TENANT_ADMIN: gestión de usuarios operativos, sus alcances y empleados.
  INSERT INTO public.role_screen_actions (tenant_id, role_id, screen_action_id, is_allowed, created_by)
  SELECT v_tenant_system_id, v_role_tenant_admin, sa.id, true, 'SYSTEM'
  FROM public.screen_actions sa
  JOIN public.screens s ON sa.screen_id = s.id
  WHERE s.screen_key IN ('USER_MANAGEMENT', 'SEC_USER_ROLE_SCOPES', 'SEC_USER_EMPLOYEE_ACCESS')
    AND sa.is_active = true
  ON CONFLICT (tenant_id, role_id, screen_action_id) DO UPDATE SET
    is_allowed = true,
    updated_by = 'SYSTEM',
    updated_at = now();

  -- Elimina concesiones históricas incompatibles con la responsabilidad definida.
  UPDATE public.role_screen_actions rsa
  SET is_allowed = false,
      updated_by = 'SYSTEM',
      updated_at = now()
  FROM public.screen_actions sa,
       public.screens s
  WHERE rsa.role_id = v_role_system_admin
    AND rsa.screen_action_id = sa.id
    AND sa.screen_id = s.id
    AND s.screen_key IN ('SEC_USER_ROLE_SCOPES', 'SEC_USER_EMPLOYEE_ACCESS');

  -- La creación de usuarios es responsabilidad exclusiva del TENANT_ADMIN.
  -- SYSTEM_ADMIN conserva la consulta y edición de los dos usuarios protegidos,
  -- pero no puede crear usuarios adicionales desde esta pantalla ni por API.
  UPDATE public.role_screen_actions rsa
  SET is_allowed = (rsa.role_id = v_role_tenant_admin),
      is_active = true,
      updated_by = 'SYSTEM',
      updated_at = now()
  FROM public.screen_actions sa,
       public.screens s,
       public.actions a
  WHERE rsa.role_id IN (v_role_system_admin, v_role_tenant_admin)
    AND rsa.screen_action_id = sa.id
    AND sa.screen_id = s.id
    AND sa.action_id = a.id
    AND s.screen_key = 'USER_MANAGEMENT'
    AND a.action_key = 'CREATE';

  IF EXISTS (
    SELECT 1
    FROM public.role_screen_actions rsa
    JOIN public.screen_actions sa ON sa.id = rsa.screen_action_id
    JOIN public.screens s ON s.id = sa.screen_id
    JOIN public.actions a ON a.id = sa.action_id
    WHERE rsa.role_id = v_role_system_admin
      AND rsa.is_active = true
      AND rsa.is_allowed = true
      AND (
        s.screen_key IN ('SEC_USER_ROLE_SCOPES', 'SEC_USER_EMPLOYEE_ACCESS')
        OR (s.screen_key = 'USER_MANAGEMENT' AND a.action_key = 'CREATE')
      )
  ) THEN
    RAISE EXCEPTION 'ERROR: SYSTEM_ADMIN conserva responsabilidades operativas de usuarios';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM (VALUES
      ('USER_MANAGEMENT', 'CREATE'),
      ('SEC_USER_ROLE_SCOPES', 'VIEW'),
      ('SEC_USER_EMPLOYEE_ACCESS', 'VIEW')
    ) required(screen_key, action_key)
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.role_screen_actions rsa
      JOIN public.screen_actions sa ON sa.id = rsa.screen_action_id
      JOIN public.screens s ON s.id = sa.screen_id
      JOIN public.actions a ON a.id = sa.action_id
      WHERE rsa.role_id = v_role_tenant_admin
        AND rsa.is_active = true
        AND rsa.is_allowed = true
        AND s.screen_key = required.screen_key
        AND a.action_key = required.action_key
    )
  ) THEN
    RAISE EXCEPTION 'ERROR: TENANT_ADMIN no recibió todas las responsabilidades operativas de usuarios';
  END IF;

  -- RRHH_ADMIN: elimina concesiones antiguas fuera de su responsabilidad.
  DELETE FROM public.role_screen_actions rsa
  USING public.screen_actions sa,
        public.screens s,
        public.system_menu_groups smg
  WHERE rsa.role_id = v_role_rrhh_admin
    AND rsa.screen_action_id = sa.id
    AND sa.screen_id = s.id
    AND s.menu_group_id = smg.id
    AND (
      smg.menu_group_key NOT IN ('APROVE', 'PROCESSES', 'REPORTS')
      OR smg.is_active = false
      OR s.is_active = false
      OR sa.is_active = false
    );

  -- RRHH_ADMIN: aprobaciones, procesos operativos y reportes
  INSERT INTO public.role_screen_actions (tenant_id, role_id, screen_action_id, is_allowed, created_by)
  SELECT v_tenant_system_id, v_role_rrhh_admin, sa.id, true, 'SYSTEM'
  FROM public.screen_actions sa
  JOIN public.screens s ON sa.screen_id = s.id
  JOIN public.system_menu_groups smg ON s.menu_group_id = smg.id
  WHERE smg.menu_group_key IN ('APROVE', 'PROCESSES', 'REPORTS')
    AND smg.is_active = true
    AND s.is_active = true
    AND sa.is_active = true
  ON CONFLICT (tenant_id, role_id, screen_action_id) DO UPDATE SET
    is_allowed = true,
    is_active = true,
    updated_by = 'SYSTEM',
    updated_at = now();

  -- RRHH_ADMIN conserva Planificación de Turnos mediante la pantalla canónica.
  INSERT INTO public.role_screen_actions (tenant_id, role_id, screen_action_id, is_allowed, created_by)
  SELECT v_tenant_system_id, v_role_rrhh_admin, sa.id, true, 'SYSTEM'
  FROM public.screen_actions sa
  JOIN public.screens s ON sa.screen_id = s.id
  WHERE s.screen_key = 'EMPLOYEE_SHIFT_PLANNING'
    AND s.is_active = true
    AND sa.is_active = true
  ON CONFLICT (tenant_id, role_id, screen_action_id) DO UPDATE SET
    is_allowed = true,
    is_active = true,
    updated_by = 'SYSTEM',
    updated_at = now();

  -- SUPERVISOR: elimina concesiones antiguas fuera de su responsabilidad.
  DELETE FROM public.role_screen_actions rsa
  USING public.screen_actions sa,
        public.screens s,
        public.system_menu_groups smg
  WHERE rsa.role_id = v_role_supervisor
    AND rsa.screen_action_id = sa.id
    AND sa.screen_id = s.id
    AND s.menu_group_id = smg.id
    AND (
      smg.menu_group_key NOT IN ('APROVE', 'ATTENDANCE', 'PROCESSES', 'REPORTS')
      OR smg.is_active = false
      OR s.is_active = false
      OR sa.is_active = false
    );

  -- SUPERVISOR: aprobaciones, planificación de turnos, procesos operativos y reportes.
  -- KIOSK es exclusivo del perfil EMPLOYEE.
  INSERT INTO public.role_screen_actions (tenant_id, role_id, screen_action_id, is_allowed, created_by)
  SELECT v_tenant_system_id, v_role_supervisor, sa.id, true, 'SYSTEM'
  FROM public.screen_actions sa
  JOIN public.screens s ON sa.screen_id = s.id
  JOIN public.system_menu_groups smg ON s.menu_group_id = smg.id
  WHERE smg.menu_group_key IN ('APROVE', 'ATTENDANCE', 'PROCESSES', 'REPORTS')
    AND smg.is_active = true
    AND s.is_active = true
    AND sa.is_active = true
  ON CONFLICT (tenant_id, role_id, screen_action_id) DO UPDATE SET
    is_allowed = true,
    is_active = true,
    updated_by = 'SYSTEM',
    updated_at = now();

  -- EMPLOYEE: elimina concesiones antiguas o inactivas.
  -- MY_ATTENDANCE y MY_SCHEDULE son interfaces heredadas reemplazadas por
  -- KIOSK_TIME_PUNCH_REQUESTS y KIOSK_SHIFT_CHANGE.
  DELETE FROM public.role_screen_actions rsa
  USING public.screen_actions sa,
        public.screens s,
        public.system_menu_groups smg
  WHERE rsa.role_id = v_role_employee
    AND rsa.screen_action_id = sa.id
    AND sa.screen_id = s.id
    AND s.menu_group_id = smg.id
    AND (
      smg.menu_group_key <> 'KIOSK'
      OR smg.is_active = false
      OR s.is_active = false
      OR sa.is_active = false
    );

  -- EMPLOYEE: KIOSK vigente
  INSERT INTO public.role_screen_actions (tenant_id, role_id, screen_action_id, is_allowed, created_by)
  SELECT v_tenant_system_id, v_role_employee, sa.id, true, 'SYSTEM'
  FROM public.screen_actions sa
  JOIN public.screens s ON sa.screen_id = s.id
  JOIN public.system_menu_groups smg ON s.menu_group_id = smg.id
  WHERE smg.menu_group_key = 'KIOSK'
    AND smg.is_active = true
    AND s.is_active = true
    AND sa.is_active = true
  ON CONFLICT (tenant_id, role_id, screen_action_id) DO UPDATE SET
    is_allowed = true,
    is_active = true,
    updated_by = 'SYSTEM',
    updated_at = now();

  -- Crear parámetros sigue siendo exclusivo de SYSTEM_ADMIN.
  -- TENANT_ADMIN conserva VIEW/EDIT/ASSIGN para valores heredados en la grilla.
  UPDATE public.role_screen_actions rsa
  SET is_allowed = false,
      updated_by = 'SYSTEM',
      updated_at = now()
  FROM public.roles r,
       public.screen_actions sa,
       public.screens s,
       public.actions a
  WHERE rsa.role_id = r.id
    AND rsa.screen_action_id = sa.id
    AND sa.screen_id = s.id
    AND sa.action_id = a.id
    AND s.screen_key = 'SYSTEM_SETTINGS_MANAGEMENT'
    AND (
      r.role_key NOT IN ('SYSTEM_ADMIN', 'TENANT_ADMIN')
      OR (r.role_key = 'SYSTEM_ADMIN' AND a.action_key = 'ASSIGN')
      OR (r.role_key = 'TENANT_ADMIN' AND a.action_key NOT IN ('VIEW', 'EDIT', 'ASSIGN'))
    );
END $$;

-- ============================================================================
-- AUTORIZACION DEL REPORTE DE MARCACIONES PARA ROLES OPERATIVOS
-- ============================================================================

INSERT INTO public.role_screen_actions (
  tenant_id, role_id, screen_action_id, is_allowed, is_active, created_by
)
SELECT role.tenant_id, role.id, screen_action.id, true, true, 'SYSTEM'
FROM public.roles AS role
JOIN public.screens AS screen
  ON screen.screen_key = 'TIME_PUNCH_REPORTS'
 AND screen.is_active = true
JOIN public.screen_actions AS screen_action
  ON screen_action.screen_id = screen.id
 AND screen_action.is_active = true
WHERE UPPER(role.role_key) IN ('SUPERVISOR', 'RRHH_ADMIN', 'RHADMIN', 'TENANT_ADMIN')
  AND role.is_active = true
ON CONFLICT (tenant_id, role_id, screen_action_id) DO UPDATE SET
  is_allowed = true,
  is_active = true,
  updated_by = 'SYSTEM',
  updated_at = now();

INSERT INTO public.report_permissions (
  tenant_id, role_id, system_report_id,
  can_view, can_export, is_active, created_by
)
SELECT
  role.tenant_id,
  role.id,
  report.id,
  true,
  true,
  true,
  'SYSTEM'
FROM public.roles AS role
CROSS JOIN public.system_reports AS report
WHERE report.report_code = 'RPT_MARCACIONES_REALIZADAS'
  AND report.is_active = true
  AND UPPER(role.role_key) IN ('SUPERVISOR', 'RRHH_ADMIN', 'RHADMIN', 'TENANT_ADMIN')
  AND role.is_active = true
  AND NOT EXISTS (
    SELECT 1
    FROM public.report_permissions AS permission
    WHERE permission.tenant_id = role.tenant_id
      AND permission.role_id = role.id
      AND permission.system_report_id = report.id
  );

UPDATE public.report_permissions AS permission
SET can_view = true,
    can_export = true,
    is_active = true,
    updated_by = 'SYSTEM',
    updated_at = now()
FROM public.roles AS role,
     public.system_reports AS report
WHERE permission.tenant_id = role.tenant_id
  AND permission.role_id = role.id
  AND permission.system_report_id = report.id
  AND report.report_code = 'RPT_MARCACIONES_REALIZADAS'
  AND UPPER(role.role_key) IN ('SUPERVISOR', 'RRHH_ADMIN', 'RHADMIN', 'TENANT_ADMIN')
  AND role.is_active = true;

-- ============================================================================
-- SECCIÓN 10: SYSTEM REPORTS (6 reportes maestros totales)
-- ============================================================================

INSERT INTO public.system_reports (report_code, report_name, report_description, handler_type_id, report_handler, application_module_id, is_active, created_by)
SELECT 'RPT_HEALTHCHECK', 'Healthcheck', 'Reporte de verificación del sistema',
  lv_handler.id, 'healthcheck.default', NULL, true, 'SYSTEM'
FROM public.lookup_values lv_handler
JOIN public.lookup_groups lg_handler ON lg_handler.id = lv_handler.lookup_group_id
WHERE lg_handler.lookup_group_key = 'REPORT_HANDLER' AND lv_handler.lookup_key = 'DEFAULT'
ON CONFLICT (report_code) DO UPDATE SET
  report_name = EXCLUDED.report_name,
  report_description = EXCLUDED.report_description,
  handler_type_id = EXCLUDED.handler_type_id,
  report_handler = EXCLUDED.report_handler,
  is_active = EXCLUDED.is_active;

-- Traducciones del reporte
INSERT INTO public.system_report_translations (system_report_id, language_code, report_name, report_description)
SELECT r.id, l.code,
  CASE WHEN l.code = 'en' THEN 'Healthcheck' ELSE 'Healthcheck' END,
  CASE WHEN l.code = 'en' THEN 'System verification report' ELSE 'Reporte de verificación del sistema' END
FROM public.system_reports r
CROSS JOIN public.system_languages l
WHERE r.report_code = 'RPT_HEALTHCHECK' AND l.code IN ('es','en')
ON CONFLICT (system_report_id, language_code) DO UPDATE SET
  report_name = EXCLUDED.report_name,
  report_description = EXCLUDED.report_description;

-- ============================================================================
-- CONSOLIDACION FINAL DEL METAMODELO DE NAVEGACION Y SEGURIDAD
-- Fuente de verdad: tt_test_db validada durante las pruebas integrales.
-- Se ejecuta al final para que ninguna seccion anterior vuelva a sobrescribir
-- el orden, el grupo o la responsabilidad efectiva de estas pantallas.
-- ============================================================================

WITH canonical_order(menu_group_key, sort_order) AS (
  VALUES
    ('MAINT', 10),
    ('SECURITY', 20),
    ('DASH', 30),
    ('CONFIG', 40),
    ('ORG', 50),
    ('APROVE', 60),
    ('EMPLOYEE', 70),
    ('ATTENDANCE', 80),
    ('PROCESSES', 90),
    ('REPORTS', 100),
    ('KIOSK', 110)
)
UPDATE public.system_menu_groups AS menu_group
SET sort_order = canonical_order.sort_order,
    is_active = true,
    updated_by = 'SYSTEM',
    updated_at = now()
FROM canonical_order
WHERE menu_group.menu_group_key = canonical_order.menu_group_key;

WITH canonical_screens(
  screen_key, screen_name, menu_label, menu_group_key,
  route_path, icon_key, sort_order, is_active
) AS (
  VALUES
    ('CATALOG_MANAGEMENT', 'Gestión de Catálogos', 'Catálogos', 'MAINT', '/dashboard/maintenance/catalogs', 'List', 20, true),
    ('CNX_PAYROLL', 'Conexión a Nómina', 'Cnx. Nómina', 'MAINT', '/inicio/seguridad/cnx_nomina', 'Settings', 90, true),
    ('LANGUAGE_MANAGEMENT', 'Gestión de Idiomas', 'Idiomas', 'MAINT', '/dashboard/security/languages', 'Globe', 30, true),
    ('MESSAGE_KEY_MANAGEMENT', 'Gestión de Claves de Mensajes', 'Mensajes', 'MAINT', '/dashboard/security/message-keys', 'MessageSquare', 50, true),
    ('ROLE_MANAGEMENT', 'Gestión de Roles', 'Roles', 'SECURITY', '/dashboard/security/roles', 'Shield', 30, true),
    ('ROLES_MANAGEMENT', 'Roles', 'Roles', 'MAINT', '/dashboard/maintenance/roles', 'Shield', 35, false),
    ('SCOPE_TYPE_MANAGEMENT', 'Gestión de Tipos de Alcance', 'Alcances', 'SECURITY', '/dashboard/security/scopes', 'Target', 40, true),
    ('SCOPE_TYPES_MANAGEMENT', 'Alcances', 'Alcances', 'MAINT', '/dashboard/maintenance/scopes', 'Layers', 70, true),
    ('SEC_ACTIONS', 'Acciones', 'Acciones', 'SECURITY', '/dashboard/security/actions', 'Zap', 90, true),
    ('SEC_MENU_GROUPS', 'Grupos de Menú', 'Grupos de Menú', 'SECURITY', '/dashboard/security/menu-groups', 'LayoutList', 100, true),
    ('SEC_ROLE_PERMS', 'Autorizacion por Rol', 'Permisos por rol', 'SECURITY', '/dashboard/security/role-permissions', 'ShieldCheck', 50, true),
    ('SEC_ROLE_SCREEN_ACTIONS', 'Permisos por Rol', 'Permisos por Rol', 'SECURITY', '/dashboard/security/role-screen-actions', 'ShieldCheck', 130, true),
    ('SEC_SCREEN_ACTIONS', 'Acciones de Pantalla', 'Acc. de Pantalla', 'SECURITY', '/dashboard/security/screen-actions', 'Link2', 140, true),
    ('SEC_SCREENS', 'Pantallas', 'Pantallas', 'SECURITY', '/dashboard/security/screens', 'Monitor', 110, true),
    ('SEC_USER_EMPLOYEE_ACCESS', 'Autorizacion Empleados por Usuario', 'Acceso empleados', 'SECURITY', '/dashboard/security/user-employee-access', 'Users', 120, true),
    ('SEC_USER_ROLE_SCOPES', 'Alcances Organizacion por Usuario', 'Alcances por usuario', 'SECURITY', '/dashboard/security/user-role-scopes', 'SlidersHorizontal', 70, true),
    ('SUBSCRIPTION_PLAN_MANAGEMENT', 'Gestión de Planes de Suscripción', 'Planes', 'MAINT', '/dashboard/security/subscription-plans', 'CreditCard', 60, true),
    ('SYSTEM_REPORT_MANAGEMENT', 'Gestión de Reportes del Sistema', 'Reportes Sistema', 'SECURITY', '/dashboard/security/system-reports', 'FileText', 80, true),
    ('SYSTEM_SETTINGS_MANAGEMENT', 'Parámetros de Configuración', 'Parámetros', 'MAINT', '/dashboard/maintenance/parameters', 'Settings', 10, true),
    ('TENANT_MANAGEMENT', 'Gestión de Tenants', 'Gestión del Tenant', 'SECURITY', '/dashboard/security/tenants', 'Building', 10, true),
    ('TRANSLATION_MANAGEMENT', 'Gestión de Traducciones', 'Traducciones', 'MAINT', '/dashboard/security/translations', 'Languages', 40, true),
    ('USER_MANAGEMENT', 'Gestión de Usuarios', 'Usuarios', 'SECURITY', '/dashboard/security/tenant-members', 'Users', 20, true),
    ('USERS_MANAGEMENT', 'Usuarios', 'Usuarios', 'MAINT', '/dashboard/maintenance/users', 'Users', 80, true)
), resolved AS (
  SELECT canonical_screens.*, menu_group.id AS menu_group_id
  FROM canonical_screens
  JOIN public.system_menu_groups AS menu_group
    ON menu_group.menu_group_key = canonical_screens.menu_group_key
)
INSERT INTO public.screens (
  screen_key, screen_name, menu_label, menu_group_id,
  route_path, icon_key, sort_order, is_active, created_by
)
SELECT
  screen_key, screen_name, menu_label, menu_group_id,
  route_path, icon_key, sort_order, is_active, 'SYSTEM'
FROM resolved
ON CONFLICT (screen_key) DO UPDATE SET
  screen_name = EXCLUDED.screen_name,
  menu_label = EXCLUDED.menu_label,
  menu_group_id = EXCLUDED.menu_group_id,
  route_path = EXCLUDED.route_path,
  icon_key = EXCLUDED.icon_key,
  sort_order = EXCLUDED.sort_order,
  is_active = EXCLUDED.is_active,
  updated_by = 'SYSTEM',
  updated_at = now();

DO $$
DECLARE
  v_tenant_id uuid;
  v_system_admin_role_id uuid;
  v_tenant_admin_role_id uuid;
BEGIN
  SELECT id INTO STRICT v_tenant_id
  FROM public.tenants
  WHERE tenant_key = 'SYSTEM';

  SELECT id INTO STRICT v_system_admin_role_id
  FROM public.roles
  WHERE tenant_id = v_tenant_id AND role_key = 'SYSTEM_ADMIN';

  SELECT id INTO STRICT v_tenant_admin_role_id
  FROM public.roles
  WHERE tenant_id = v_tenant_id AND role_key = 'TENANT_ADMIN';

  -- SYSTEM_ADMIN conserva las definiciones, pero no administra los alcances
  -- operativos ni el acceso a empleados de los usuarios del tenant.
  INSERT INTO public.role_screen_actions (
    tenant_id, role_id, screen_action_id, is_allowed, is_active, created_by
  )
  SELECT v_tenant_id, v_system_admin_role_id, screen_action.id, false, true, 'SYSTEM'
  FROM public.screen_actions AS screen_action
  JOIN public.screens AS screen ON screen.id = screen_action.screen_id
  WHERE screen.screen_key IN ('SEC_USER_ROLE_SCOPES', 'SEC_USER_EMPLOYEE_ACCESS')
  ON CONFLICT (tenant_id, role_id, screen_action_id) DO UPDATE SET
    is_allowed = false,
    is_active = true,
    updated_by = 'SYSTEM',
    updated_at = now();

  -- La accion ASSIGN del catalogo maestro de parametros no corresponde a
  -- SYSTEM_ADMIN; este perfil crea y edita la definicion completa.
  DELETE FROM public.role_screen_actions AS permission
  USING public.screen_actions AS screen_action,
        public.screens AS screen,
        public.actions AS action
  WHERE permission.role_id = v_system_admin_role_id
    AND permission.screen_action_id = screen_action.id
    AND screen_action.screen_id = screen.id
    AND screen_action.action_id = action.id
    AND screen.screen_key = 'SYSTEM_SETTINGS_MANAGEMENT'
    AND action.action_key = 'ASSIGN';

  -- TENANT_ADMIN no administra el metamodelo de roles del sistema.
  DELETE FROM public.role_screen_actions AS permission
  USING public.screen_actions AS screen_action,
        public.screens AS screen
  WHERE permission.role_id = v_tenant_admin_role_id
    AND permission.screen_action_id = screen_action.id
    AND screen_action.screen_id = screen.id
    AND screen.screen_key = 'ROLE_MANAGEMENT';

END $$;

-- BEGIN GENERATED COMPLETE TRANSLATIONS ES_EN_PT
-- Traducciones completas del metamodelo del sistema (es, en, pt).
-- Idempotente por clave natural: reemplaza únicamente estos tres idiomas.
-- Corrige el legado donde portugués fue registrado por error con código "fr".
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.system_languages
    WHERE code = 'fr'
      AND lower(language_name) IN ('portugués', 'português', 'portuguese')
  ) THEN
    DELETE FROM public.system_menu_group_translations WHERE language_code = 'fr';
    DELETE FROM public.screen_translations WHERE language_code = 'fr';
    DELETE FROM public.action_translations WHERE language_code = 'fr';
    DELETE FROM public.lookup_group_translations WHERE language_code = 'fr';
    DELETE FROM public.lookup_value_translations WHERE language_code = 'fr';
    DELETE FROM public.system_report_translations WHERE language_code = 'fr';
    DELETE FROM public.report_parameter_translations WHERE language_code = 'fr';
    DELETE FROM public.system_message_translations WHERE language_code = 'fr';
    DELETE FROM public.system_languages WHERE code = 'fr';
  END IF;
END $$;

INSERT INTO public.system_languages (code, language_name, is_active, is_default)
VALUES ('pt', 'Português', true, false)
ON CONFLICT (code) DO UPDATE SET
  language_name = EXCLUDED.language_name,
  is_active = EXCLUDED.is_active;

DELETE FROM public.system_menu_group_translations WHERE language_code IN ('es', 'en', 'pt');
DELETE FROM public.screen_translations WHERE language_code IN ('es', 'en', 'pt');
DELETE FROM public.action_translations WHERE language_code IN ('es', 'en', 'pt');
DELETE FROM public.lookup_group_translations WHERE language_code IN ('es', 'en', 'pt');
DELETE FROM public.lookup_value_translations WHERE language_code IN ('es', 'en', 'pt');
DELETE FROM public.system_report_translations WHERE language_code IN ('es', 'en', 'pt');
DELETE FROM public.report_parameter_translations WHERE language_code IN ('es', 'en', 'pt');
DELETE FROM public.system_message_translations WHERE language_code IN ('es', 'en', 'pt');

