  ('MSG.LOGIN.WELCOME', 'Welcome', 'Bem-vindo'),
  ('MSG.ONBOARDING.COMPLETE', 'Configuration completed', 'Configuração concluída'),
  ('MSG.ONBOARDING.START', 'Initial configuration', 'Configuração inicial'),
  ('MSG.ONBOARDING.STEP1', 'Step 1: Create Tenant', 'Etapa 1: Criar Tenant'),
  ('MSG.ONBOARDING.STEP2', 'Step 2: Create Administrator', 'Etapa 2: Criar Administrador');

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.system_menu_groups b LEFT JOIN seed_menu_group_i18n t ON t.entity_key = b.menu_group_key WHERE t.entity_key IS NULL) THEN
    RAISE EXCEPTION 'Faltan traducciones para uno o más grupos de menú';
  END IF;
  IF EXISTS (SELECT 1 FROM public.screens b LEFT JOIN seed_screen_i18n t ON t.entity_key = b.screen_key WHERE t.entity_key IS NULL) THEN
    RAISE EXCEPTION 'Faltan traducciones para una o más pantallas';
  END IF;
  IF EXISTS (SELECT 1 FROM public.actions b LEFT JOIN seed_action_i18n t ON t.entity_key = b.action_key WHERE t.entity_key IS NULL) THEN
    RAISE EXCEPTION 'Faltan traducciones para una o más acciones';
  END IF;
  IF EXISTS (SELECT 1 FROM public.lookup_groups b LEFT JOIN seed_lookup_group_i18n t ON t.entity_key = b.lookup_group_key WHERE t.entity_key IS NULL) THEN
    RAISE EXCEPTION 'Faltan traducciones para uno o más grupos de catálogos';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.lookup_values b
    JOIN public.lookup_groups g ON g.id = b.lookup_group_id
    LEFT JOIN seed_lookup_value_i18n t
      ON t.group_key = g.lookup_group_key AND t.entity_key = b.lookup_key
    WHERE b.tenant_id IS NULL AND t.entity_key IS NULL
  ) THEN
    RAISE EXCEPTION 'Faltan traducciones para uno o más ítems de catálogos';
  END IF;
  IF EXISTS (SELECT 1 FROM public.system_reports b LEFT JOIN seed_report_i18n t ON t.entity_key = b.report_code WHERE t.entity_key IS NULL) THEN
    RAISE EXCEPTION 'Faltan traducciones para uno o más reportes';
  END IF;
  IF EXISTS (SELECT 1 FROM public.report_parameters b LEFT JOIN seed_report_parameter_i18n t ON t.entity_key = b.parameter_key WHERE t.entity_key IS NULL) THEN
    RAISE EXCEPTION 'Faltan traducciones para uno o más parámetros de reportes';
  END IF;
  IF EXISTS (SELECT 1 FROM public.system_message_keys b LEFT JOIN seed_message_i18n t ON t.entity_key = b.message_key WHERE t.entity_key IS NULL) THEN
    RAISE EXCEPTION 'Faltan traducciones para uno o más mensajes';
  END IF;
END $$;

INSERT INTO public.system_menu_group_translations
  (menu_group_id, language_code, menu_group_name, menu_group_short_name)
SELECT g.id, tr.language_code, tr.group_name, tr.short_name
FROM public.system_menu_groups g
JOIN seed_menu_group_i18n t ON t.entity_key = g.menu_group_key
CROSS JOIN LATERAL (VALUES
  ('es'::varchar, g.menu_group_name, COALESCE(g.menu_group_short_name, g.menu_group_name)),
  ('en'::varchar, t.en_name, t.en_short),
  ('pt'::varchar, t.pt_name, t.pt_short)
) tr(language_code, group_name, short_name);

INSERT INTO public.screen_translations
  (screen_id, language_code, screen_name, menu_label)
SELECT s.id, tr.language_code, tr.screen_name, tr.menu_label
FROM public.screens s
JOIN seed_screen_i18n t ON t.entity_key = s.screen_key
CROSS JOIN LATERAL (VALUES
  ('es'::varchar, s.screen_name, COALESCE(s.menu_label, s.screen_name)),
  ('en'::varchar, t.en_name, t.en_menu),
  ('pt'::varchar, t.pt_name, t.pt_menu)
) tr(language_code, screen_name, menu_label);

INSERT INTO public.action_translations
  (action_id, language_code, action_name)
SELECT a.id, tr.language_code, tr.action_name
FROM public.actions a
JOIN seed_action_i18n t ON t.entity_key = a.action_key
CROSS JOIN LATERAL (VALUES
  ('es'::varchar, a.action_name),
  ('en'::varchar, t.en_name),
  ('pt'::varchar, t.pt_name)
) tr(language_code, action_name);

INSERT INTO public.lookup_group_translations
  (lookup_group_id, language_code, label, short_label)
SELECT g.id, tr.language_code, tr.label, tr.short_label
FROM public.lookup_groups g
JOIN seed_lookup_group_i18n t ON t.entity_key = g.lookup_group_key
CROSS JOIN LATERAL (VALUES
  ('es'::varchar, g.lookup_group_label, g.lookup_group_short_label),
  ('en'::varchar, t.en_label, t.en_short),
  ('pt'::varchar, t.pt_label, t.pt_short)
) tr(language_code, label, short_label);

INSERT INTO public.lookup_value_translations
  (lookup_value_id, language_code, label, short_label)
SELECT v.id, tr.language_code, tr.label,
       CASE
         WHEN tr.language_code = 'es'
          AND g.lookup_group_key = 'TIME_PUNCH_CHANGE_REQUEST_TYPE'
           THEN v.lookup_label
         WHEN tr.language_code = 'es' THEN v.lookup_short_label
         WHEN g.lookup_group_key IN ('ATTENDANCE_TIMEZONE', 'CURRENCY', 'OUTPUT_FORMAT') THEN v.lookup_short_label
         ELSE tr.label
       END AS short_label
FROM public.lookup_values v
JOIN public.lookup_groups g ON g.id = v.lookup_group_id
JOIN seed_lookup_value_i18n t
  ON t.group_key = g.lookup_group_key AND t.entity_key = v.lookup_key
CROSS JOIN LATERAL (VALUES
  ('es'::varchar, v.lookup_label),
  ('en'::varchar, t.en_label),
  ('pt'::varchar, t.pt_label)
) tr(language_code, label)
WHERE v.tenant_id IS NULL;

INSERT INTO public.system_report_translations
  (system_report_id, language_code, report_name, report_description, report_notes)
SELECT r.id, tr.language_code, tr.report_name, tr.report_description, tr.report_notes
FROM public.system_reports r
JOIN seed_report_i18n t ON t.entity_key = r.report_code
CROSS JOIN LATERAL (VALUES
  ('es'::varchar, r.report_name, r.report_description, r.report_notes),
  ('en'::varchar, t.en_name, t.en_description, t.en_notes),
  ('pt'::varchar, t.pt_name, t.pt_description, t.pt_notes)
) tr(language_code, report_name, report_description, report_notes);

INSERT INTO public.report_parameter_translations
  (report_parameter_id, language_code, parameter_label, parameter_description)
SELECT p.id, tr.language_code, tr.parameter_label, tr.parameter_description
FROM public.report_parameters p
JOIN seed_report_parameter_i18n t ON t.entity_key = p.parameter_key
CROSS JOIN LATERAL (VALUES
  ('es'::varchar, p.parameter_label, p.parameter_description),
  ('en'::varchar, t.en_label, t.en_description),
  ('pt'::varchar, t.pt_label, t.pt_description)
) tr(language_code, parameter_label, parameter_description);

INSERT INTO public.system_message_translations
  (message_key, message_key_id, language_code, translated_text, is_active)
SELECT m.message_key, m.id, tr.language_code, tr.translated_text, true
FROM public.system_message_keys m
JOIN seed_message_i18n t ON t.entity_key = m.message_key
CROSS JOIN LATERAL (VALUES
  ('es'::varchar, m.default_text),
  ('en'::varchar, t.en_text),
  ('pt'::varchar, t.pt_text)
) tr(language_code, translated_text);

DO $$
DECLARE
  v_expected integer;
  v_actual integer;
BEGIN
  SELECT 3 * (
    (SELECT count(*) FROM public.system_menu_groups) +
    (SELECT count(*) FROM public.screens) +
    (SELECT count(*) FROM public.actions) +
    (SELECT count(*) FROM public.lookup_groups) +
    (SELECT count(*) FROM public.lookup_values WHERE tenant_id IS NULL) +
    (SELECT count(*) FROM public.system_reports) +
    (SELECT count(*) FROM public.report_parameters) +
    (SELECT count(*) FROM public.system_message_keys)
  ) INTO v_expected;

  SELECT
    (SELECT count(*) FROM public.system_menu_group_translations WHERE language_code IN ('es', 'en', 'pt')) +
    (SELECT count(*) FROM public.screen_translations WHERE language_code IN ('es', 'en', 'pt')) +
    (SELECT count(*) FROM public.action_translations WHERE language_code IN ('es', 'en', 'pt')) +
    (SELECT count(*) FROM public.lookup_group_translations WHERE language_code IN ('es', 'en', 'pt')) +
    (SELECT count(*) FROM public.lookup_value_translations WHERE language_code IN ('es', 'en', 'pt')) +
    (SELECT count(*) FROM public.system_report_translations WHERE language_code IN ('es', 'en', 'pt')) +
    (SELECT count(*) FROM public.report_parameter_translations WHERE language_code IN ('es', 'en', 'pt')) +
    (SELECT count(*) FROM public.system_message_translations WHERE language_code IN ('es', 'en', 'pt'))
  INTO v_actual;

  IF v_actual <> v_expected THEN
    RAISE EXCEPTION 'Cobertura de traducciones incompleta: esperado %, obtenido %', v_expected, v_actual;
  END IF;

  RAISE NOTICE 'Traducciones ES/EN/PT verificadas: % filas', v_actual;
END $$;
-- END GENERATED COMPLETE TRANSLATIONS ES_EN_PT

