    "lookup_value_translations": 795,
    "report_parameters": 46,
    "report_parameter_translations": 138,
    "report_permissions": 3,
    "roles": 5,
    "role_screen_actions": 397,
    "scope_types": 7,
    "screen_actions": 265,
    "api_authorization_rules": 378,
    "data_access_authorization_rules": 141,
    "screens": 68,
    "screen_translations": 204,
    "states": 183,
    "subscription_plans": 3,
    "system_languages": 3,
    "system_menu_groups": 11,
    "system_menu_group_translations": 33,
    "system_message_keys": 5,
    "system_message_translations": 15,
    "system_reports": 6,
    "system_report_translations": 18,
    "system_settings": 32,
    "system_shift_templates": 5,
    "tenant_onboarding": 1,
    "tenants": 1,
    "user_roles": 1,
    "users": 1,
    "v_gender_group_id": 1,
    "v_super_admin_role_id": 1,
    "work_patterns": 2,
    "shift_coverage_requirements": 1,
    "shift_planning_realtime_state": 1
  }'::jsonb;
  existing_baseline jsonb;
  current_seed_version jsonb;
  table_entry record;
  table_rows jsonb;
  baseline_tables jsonb := '{}'::jsonb;
  baseline_counts jsonb := '{}'::jsonb;
  baseline_table_count integer := 0;
  actual_row_count bigint;
  expected_row_count bigint;
  schema_fingerprint text;
BEGIN
  SELECT value INTO existing_baseline
  FROM public.kv_store_e19f2094
  WHERE key = baseline_key;

  SELECT value INTO current_seed_version
  FROM public.kv_store_e19f2094
  WHERE key = 'seed.version';

  IF current_seed_version IS NULL
     OR current_seed_version->>'version' IS DISTINCT FROM '2026-07-23-FACTORY-V17' THEN
    RAISE EXCEPTION 'No se puede crear la fotografia: seed.version no corresponde a 2026-07-23-FACTORY-V17';
  END IF;

  IF existing_baseline IS NOT NULL
     AND existing_baseline->>'format_version' = '2'
     AND existing_baseline->'seed_version' = current_seed_version THEN
    RAISE NOTICE 'Fotografia de fabrica vigente; se conserva sin sobrescribir.';
    RETURN;
  END IF;

  FOR table_entry IN
    SELECT tablename AS table_name
    FROM pg_catalog.pg_tables
    WHERE schemaname = 'public'
    ORDER BY tablename
  LOOP
    expected_row_count := COALESCE((expected_nonempty_counts->>table_entry.table_name)::bigint, 0);

    IF table_entry.table_name = 'kv_store_e19f2094' THEN
      SELECT count(*) INTO actual_row_count
      FROM public.kv_store_e19f2094
      WHERE key <> baseline_key;

      SELECT COALESCE(jsonb_agg(row_json ORDER BY row_json::text), '[]'::jsonb)
        INTO table_rows
      FROM (
        SELECT to_jsonb(source_row) AS row_json
        FROM public.kv_store_e19f2094 AS source_row
        WHERE key <> baseline_key
      ) AS serialized_rows;
    ELSE
      EXECUTE format('SELECT count(*) FROM public.%I', table_entry.table_name)
        INTO actual_row_count;

      EXECUTE format(
        'SELECT COALESCE(jsonb_agg(row_json ORDER BY row_json::text), ''[]''::jsonb)
           FROM (
             SELECT to_jsonb(source_row) AS row_json
             FROM public.%I AS source_row
           ) AS serialized_rows',
        table_entry.table_name
      ) INTO table_rows;
    END IF;

    IF actual_row_count <> expected_row_count THEN
      RAISE EXCEPTION
        'No se puede actualizar la fotografia: public.% no esta en estado de fabrica (esperado %, obtenido %)',
        table_entry.table_name,
        expected_row_count,
        actual_row_count;
    END IF;

    baseline_tables := baseline_tables || jsonb_build_object(table_entry.table_name, table_rows);
    baseline_counts := baseline_counts || jsonb_build_object(table_entry.table_name, jsonb_array_length(table_rows));
    baseline_table_count := baseline_table_count + 1;
  END LOOP;

  PERFORM pg_catalog.set_config('search_path', 'pg_catalog', true);
  WITH schema_objects AS (
    SELECT format('table|%s', c.relname) AS definition
    FROM pg_catalog.pg_class c
    JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p')
    UNION ALL
    SELECT format(
      'column|%s|%s|%s|%s|%s',
      columns.table_name,
      columns.column_name,
      columns.data_type,
      columns.is_nullable,
      COALESCE(columns.column_default, '')
    )
    FROM information_schema.columns
    WHERE table_schema = 'public'
    UNION ALL
    SELECT format('constraint|%s|%s|%s', c.relname, con.conname, pg_get_constraintdef(con.oid, true))
    FROM pg_catalog.pg_constraint con
    JOIN pg_catalog.pg_class c ON c.oid = con.conrelid
    JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND con.contype IN ('p', 'u', 'f', 'x')
    UNION ALL
    SELECT format('index|%s|%s', indexname, indexdef)
    FROM pg_catalog.pg_indexes
    WHERE schemaname = 'public'
    UNION ALL
    SELECT format('view|%s|%s', c.relname, pg_get_viewdef(c.oid, true))
    FROM pg_catalog.pg_class c
    JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relkind IN ('v', 'm')
    UNION ALL
    SELECT format('trigger|%s|%s', c.relname, pg_get_triggerdef(t.oid, true))
    FROM pg_catalog.pg_trigger t
    JOIN pg_catalog.pg_class c ON c.oid = t.tgrelid
    JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND NOT t.tgisinternal
  )
  SELECT md5(string_agg(definition, E'\n' ORDER BY definition))
    INTO schema_fingerprint
  FROM schema_objects;
  PERFORM pg_catalog.set_config('search_path', 'public, pg_catalog', true);

  INSERT INTO public.kv_store_e19f2094 (key, value)
  VALUES (
    baseline_key,
    jsonb_build_object(
      'format_version', 2,
      'seed_version', current_seed_version,
      'schema_fingerprint', schema_fingerprint,
      'table_count', (SELECT count(*) FROM pg_catalog.pg_tables WHERE schemaname = 'public'),
      'row_counts', baseline_counts,
      'tables', baseline_tables
    )
  )
  ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;

  RAISE NOTICE 'Fotografia de fabrica v2 creada/actualizada: % tablas, esquema %.', baseline_table_count, schema_fingerprint;
END $$;

COMMIT;
